UIScoreExplosionParticle=function(game,x,y,key,frame){Phaser.Particle.call(this,game,x,y,key,frame);this.kill();};UIScoreExplosionParticle.prototype=Object.create(Phaser.Particle.prototype);UIScoreExplosionParticle.prototype.constructor=UIScoreExplosionParticle;UIScoreExplosionParticle.prototype.onEmit=function(){this.body.x+=this.body.velocity.x*(Math.random()*6.0+1.0)/15.0;this.body.y+=this.body.velocity.y*(Math.random()*6.0+1.0)/15.0;};UIScoreExplosionParticle.prototype.update=function(){this.alpha=Math.max(0.0,this.alpha-(0.0094-Math.random()*0.004));this.scale.set(this.scale.x+0.02,this.scale.y+0.02);};UIScoreExplosionParticle.prototype.retire=function(){this.kill();};